/**
 * Avatars for the source credit on a reflection card: a human author gets a
 * face, a reference work gets an emblem (owner's Figma, 2026-09-26).
 *
 * - `ryle`: J. C. Ryle, the engraving in The Illustrated London News, 20 March
 *   1880, p. 277 ("The Very Rev. J. C. Ryle, Dean of Salisbury", after a
 *   photograph by Samuel A. Walker). Public domain; scanned from the Internet
 *   Archive (sim_illustrated-london-news_1880-03-20_76_2129), cropped to head
 *   and beard. The owner picked the engraved look; Getty sells the same
 *   engraving, and this scan is used instead so its provenance is clean.
 * - `scroll`: line-art scroll, for notes on the original language.
 * - `book`: line-art open book, for historical notes.
 *
 * Emblems are white line art on transparency, drawn 86x63 inside the 86px
 * circle on a 1920x1080 frame (the Figma layer's box).
 */
export const SOURCE_PORTRAIT_IDS = ["ryle", "scroll", "book"] as const
export type SourcePortraitId = (typeof SOURCE_PORTRAIT_IDS)[number]

/** True for an emblem (line art in a ring), false for a photo filling the circle. */
export const SOURCE_PORTRAIT_IS_EMBLEM: Record<SourcePortraitId, boolean> = {
  ryle: false,
  scroll: true,
  book: true,
}

const RYLE_JPEG_BASE64 =
  ""

const SCROLL_PNG_BASE64 =
  ""

const BOOK_PNG_BASE64 =
  ""

export const SOURCE_PORTRAIT_URIS: Record<SourcePortraitId, string> = {
  ryle: `data:image/jpeg;base64,${RYLE_JPEG_BASE64}`,
  scroll: `data:image/png;base64,${SCROLL_PNG_BASE64}`,
  book: `data:image/png;base64,${BOOK_PNG_BASE64}`,
}
